OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 total_written = 0;
    OPJ_BOOL success = OPJ_TRUE;

    while (total_written < p_total_data_size && success) {
        OPJ_UINT32 bytes_to_write = p_total_data_size - total_written;
        OPJ_UINT32 bytes_written = 0;

        if (!opj_j2k_write_tile_part(p_j2k, p_data + total_written, &bytes_written, p_stream, p_manager)) {
            success = OPJ_FALSE;
            break;
        }

        total_written += bytes_written;
    }

    *p_data_written = total_written;

    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 bytes_written = 0;
    OPJ_BOOL success = OPJ_TRUE;
    OPJ_UINT32 tile_no = 0;
    OPJ_UINT32 num_tiles = p_j2k->cinfo->image->numresolution;

    for (tile_no = 0; tile_no < num_tiles; ++tile_no) {
        OPJ_UINT32 tile_part_count = 0;
        OPJ_UINT32 tile_part_index;

        for (tile_part_index = 0; tile_part_index < p_j2k->cinfo->cp->tw * p_j2k->cinfo->cp->th;
             ++tile_part_index) {
            OPJ_BYTE *tile_part_data = NULL;
            OPJ_UINT32 tile_part_size = 0;

            if (tile_part_index == 0) {
                // Write the header for the first tile part
                if (p_j2k->cinfo->cp->tp_on) {
                    // Mark the start of a tile part
                    if (bytes_written + 2 > p_total_data_size) {
                        success = OPJ_FALSE;
                        break;
                    }
                    p_data[bytes_written++] = 0xff;
                    p_data[bytes_written++] = 0x91; // SOT marker
                }
            } else {
                // Subsequent tile part
                if (bytes_written + 2 > p_total_data_size) {
                    success = OPJ_FALSE;
                    break;
                }
                p_data[bytes_written++] = 0xff;
                p_data[bytes_written++] = 0x92; // SOD marker
            }

            // Simulate getting the tile part data and its size
            tile_part_data = p_j2k->tile_data[tile_part_index];
            tile_part_size = p_j2k->tile_sizes[tile_part_index];

            if (bytes_written + tile_part_size > p_total_data_size) {
                success = OPJ_FALSE;
                break;
            }

            // Copy tile part data into the buffer
            memcpy(&p_data[bytes_written], tile_part_data, tile_part_size);
            bytes_written += tile_part_size;

            // Update event manager
            opj_event_msg(p_manager, EVT_DEBUG, "Wrote tile part %u (size %u bytes)\n", tile_part_index,
                          tile_part_size);
        }

        if (!success) {
            break;
        }
    }

    if (success) {
        *p_data_written = bytes_written;
        opj_stream_write_data(p_stream, p_data, bytes_written);
    }

    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 total_bytes_written = 0;
    OPJ_BOOL success = OPJ_TRUE;

    for (OPJ_UINT32 tile_index = 0; tile_index < p_j2k->cinfo->numresolution; ++tile_index) {
        for (OPJ_UINT32 part_index = 0; part_index < p_j2k->cinfo->tcp_numlayers; ++part_index) {
            OPJ_UINT32 header_size = 0;
            OPJ_UINT32 data_size = 0;

            /* Simulate header and data size calculation based on the tile part logic. */
            if (part_index == 0) {
                header_size = 12; // Example size for initial tile part header.
            } else {
                header_size = 8;  // Example size for subsequent tile part header.
            }

            data_size = 1024; // Example data size per tile part.

            if (total_bytes_written + header_size + data_size > p_total_data_size) {
                success = OPJ_FALSE;
                opj_event_msg(p_manager, EVT_ERROR, "Not enough space to write tile part data.\n");
                break;
            }

            /* Write header to p_data. Placeholder for actual header writing logic. */
            for (OPJ_UINT32 i = 0; i < header_size; ++i) {
                p_data[total_bytes_written + i] = 0xFF; // Example placeholder data.
            }

            total_bytes_written += header_size;

            /* Write data to p_data. Placeholder for actual data writing logic. */
            for (OPJ_UINT32 i = 0; i < data_size; ++i) {
                p_data[total_bytes_written + i] = 0x00; // Example placeholder data.
            }

            total_bytes_written += data_size;

            /* Simulate stream writing. Placeholder for actual stream writing logic. */
            if (opj_stream_write(p_stream, p_data, total_bytes_written) != total_bytes_written) {
                success = OPJ_FALSE;
                opj_event_msg(p_manager, EVT_ERROR, "Failed to write tile part to stream.\n");
                break;
            }
        }

        if (!success) {
            break;
        }
    }

    *p_data_written = total_bytes_written;
    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 total_written = 0;
    OPJ_BOOL result = OPJ_TRUE;

    for (OPJ_UINT32 tile_index = 0; result && (tile_index < p_j2k->number_of_tiles); ++tile_index) {
        opj_tcp_t *tile_part = p_j2k->tile_manager[tile_index];
        OPJ_UINT32 tile_data_size = tile_part->data_size;
        OPJ_UINT32 bytes_to_write = (total_written + tile_data_size) <= p_total_data_size ?
                                    tile_data_size : p_total_data_size - total_written;

        if (bytes_to_write > 0) {
            OPJ_SIZE_T written;

            if (!opj_stream_write_data(p_stream, p_data + total_written, bytes_to_write, p_manager, &written)) {
                result = OPJ_FALSE;
            } else {
                total_written += (OPJ_UINT32)written;
            }
        }
    }

    *p_data_written = total_written;
    return result;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 total_bytes_written = 0;
    OPJ_UINT32 tile_idx = 0;
    OPJ_BOOL success = OPJ_TRUE;

    for (tile_idx = 0; tile_idx < p_j2k->number_of_tiles; tile_idx++) {
        OPJ_UINT32 tile_part_idx;
        opj_tile_t *tile = &p_j2k->tiles[tile_idx];

        for (tile_part_idx = 0; tile_part_idx < tile->number_of_parts; tile_part_idx++) {
            opj_tile_part_t *tile_part = &tile->tile_parts[tile_part_idx];
            OPJ_UINT32 header_size = tile_part->header_size;
            OPJ_UINT32 data_size = tile_part->data_size;
            OPJ_UINT32 bytes_to_write = header_size + data_size;

            if (total_bytes_written + bytes_to_write > p_total_data_size) {
                success = OPJ_FALSE;
                opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Not enough space to write tile part data.\n");
                break;
            }

            if (header_size > 0) {
                opj_memcpy(p_data + total_bytes_written, tile_part->header_data, header_size);
                total_bytes_written += header_size;
            }

            if (data_size > 0) {
                opj_memcpy(p_data + total_bytes_written, tile_part->data, data_size);
                total_bytes_written += data_size;
            }

            if (opj_stream_write_data(p_stream, p_data + (total_bytes_written - bytes_to_write), bytes_to_write) != bytes_to_write) {
                success = OPJ_FALSE;
                opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Failed to write tile part to stream.\n");
                break;
            }
        }

        if (!success) {
            break;
        }
    }

    *p_data_written = total_bytes_written;
    return success;
}
